from collections import Counter
def mode_block(g,bs,skip=None):
    res=[]
    for i in range(0,len(g),bs):
        row=[]
        for j in range(0,len(g[0]),bs):
            vals=[g[a][b] for a in range(i,i+bs) for b in range(j,j+bs) if skip is None or g[a][b]!=skip]
            row.append(Counter(vals).most_common(1)[0][0])
        res.append(row)
    return res
